package com.secretnotes;
import android.content.*;import android.view.*;import android.widget.*;import androidx.recyclerview.widget.RecyclerView;import java.text.*;import java.util.*;
public class NoteAdapter extends RecyclerView.Adapter<NoteAdapter.H>{interface Click{void go(Note n);}Context c;ArrayList<Note> notes=new ArrayList<>();Click click;NoteAdapter(Context x,Click k){c=x;click=k;}void setNotes(ArrayList<Note> n){notes=n;notifyDataSetChanged();}public H onCreateViewHolder(ViewGroup p,int v){return new H(View.inflate(c,R.layout.item_note,null));}public void onBindViewHolder(H h,int i){Note n=notes.get(i);h.title.setText(n.title);h.body.setText(n.body.replace('\n',' '));h.date.setText(new SimpleDateFormat("MMM d, yyyy • h:mm a",Locale.getDefault()).format(new Date(n.updated)));h.itemView.setOnClickListener(v->click.go(n));}public int getItemCount(){return notes.size();}class H extends RecyclerView.ViewHolder{TextView title,body,date;H(View v){super(v);title=v.findViewById(R.id.itemTitle);body=v.findViewById(R.id.itemBody);date=v.findViewById(R.id.itemDate);}}}
